// Lane 4 scratch: spend guard behaviour with scripted fake clients / stubbed fetch. No network, no key.
import { mkdtempSync, existsSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import Anthropic from '/tmp/tailor-peer-review/snapshot/node_modules/@anthropic-ai/sdk/index.js';
import { createSpendGuard } from '/tmp/tailor-peer-review/snapshot/src/agent/spend.ts';
import { createAnthropicProvider, type MessagesClientLike, type ParsedMessageLike } from '/tmp/tailor-peer-review/snapshot/src/agent/anthropic-provider.ts';

const dir = mkdtempSync(join(tmpdir(), 'lane4-spend-'));
const wire = { type: 'answer', text: 'ok', clarification: null, proposal: null, explanation: null, traceId: null, spanIds: null, knowledgeIds: [], capabilityId: null, reason: null };
const req = { messages: [{ role: 'system' as const, content: 'SYS' }, { role: 'user' as const, content: 'hello' }], responseSchema: 'agent_action' as const, maxOutputTokens: 4000 };
const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));

// --- 1. concurrency: N concurrent calls all pass the check before any record() ---
{
  const ledgerPath = join(dir, 'a', 'spend-ledger.json');
  const spend = createSpendGuard({ capUsd: 0.10, ledgerPath });
  let started = 0;
  const client: MessagesClientLike = { messages: { async parse(): Promise<ParsedMessageLike> {
    started++; await sleep(100);
    // realistic heavy call: 15k input, 4k output = $0.07
    return { stop_reason: 'end_turn', usage: { input_tokens: 15000, output_tokens: 4000, output_tokens_details: { thinking_tokens: 3000 } }, parsed_output: wire };
  } } };
  const p = createAnthropicProvider({ apiKey: 'placeholder-not-a-key', spend, client });
  const results = await Promise.allSettled(Array.from({ length: 6 }, () => p.complete(req)));
  const ok = results.filter(r => r.status === 'fulfilled').length;
  const s = spend.summary();
  console.log(`[1] cap=$0.10 concurrent=6 -> calls started=${started} fulfilled=${ok} spentUsd=${s.spentUsd.toFixed(4)} remaining=${s.remainingUsd} worstCaseOneCall=$${spend.worstCaseUsd(5, 4000).toFixed(4)}`);
  // sequential afterwards is refused
  try { await p.complete(req); console.log('[1] sequential after overshoot: ALLOWED (unexpected)'); } catch (e) { console.log(`[1] sequential after overshoot: refused kind=${(e as any).kind}`); }
}

// --- 2. durability: ledger before/during/after a call that never completes (crash window) ---
{
  const ledgerPath = join(dir, 'b', 'spend-ledger.json');
  const spend = createSpendGuard({ capUsd: 1, ledgerPath });
  const client: MessagesClientLike = { messages: { parse: () => new Promise<ParsedMessageLike>(() => { /* never resolves: simulates crash/abort mid-call */ }) } };
  const p = createAnthropicProvider({ apiKey: 'placeholder-not-a-key', spend, client });
  void p.complete(req);
  await sleep(50);
  console.log(`[2] while call in flight: ledger file exists=${existsSync(ledgerPath)} summary.calls=${spend.summary().calls} spentUsd=${spend.summary().spentUsd}`);
}

// --- 3. thinking tokens are NOT added on top of output_tokens ---
{
  const spend = createSpendGuard({ capUsd: 1 });
  spend.record({ inputTokens: 1000, outputTokens: 2000, thinkingTokens: 1500, cacheReadInputTokens: 10000, cacheCreationInputTokens: 4000 }, 'm', 'plan');
  const s = spend.summary();
  const expected = (1000 * 2 + 2000 * 10 + 10000 * 0.2 + 4000 * 2.5) / 1e6;
  console.log(`[3] spentUsd=${s.spentUsd} expected(no thinking add-on)=${expected} thinkingTokens(tracked only)=${s.thinkingTokens}`);
}

// --- 4. real SDK client with stubbed fetch: 2x 529/500 then 200 => 3 HTTP attempts, 1 guard check, 1 record ---
{
  const ledgerPath = join(dir, 'c', 'spend-ledger.json');
  const spend = createSpendGuard({ capUsd: 1, ledgerPath });
  let attempts = 0;
  const body = { id: 'msg_x', type: 'message', role: 'assistant', model: 'claude-sonnet-5-5', content: [{ type: 'text', text: JSON.stringify(wire) }], stop_reason: 'end_turn', stop_sequence: null, usage: { input_tokens: 100, output_tokens: 50, output_tokens_details: { thinking_tokens: 10 }, cache_creation_input_tokens: null, cache_read_input_tokens: null } };
  const stubFetch = async (): Promise<Response> => {
    attempts++;
    if (attempts <= 2) return new Response(JSON.stringify({ type: 'error', error: { type: 'overloaded_error', message: 'Overloaded' } }), { status: 529, headers: { 'content-type': 'application/json', 'retry-after-ms': '10' } });
    return new Response(JSON.stringify(body), { status: 200, headers: { 'content-type': 'application/json' } });
  };
  const sdk = new Anthropic({ apiKey: 'placeholder-not-a-key', maxRetries: 2, timeout: 60000, fetch: stubFetch as any });
  let checks = 0;
  const origCheck = spend.check.bind(spend); spend.check = (u: number) => { checks++; origCheck(u); };
  const p = createAnthropicProvider({ apiKey: 'placeholder-not-a-key', spend, client: sdk as unknown as MessagesClientLike });
  const r = await p.complete(req);
  console.log(`[4] outcome=${r.action.type} usage=${JSON.stringify(r.usage)} http_attempts=${attempts} guard.check calls=${checks} ledger.calls=${spend.summary().calls}`);
  console.log(`[4] ledger on disk: ${JSON.stringify(JSON.parse(readFileSync(ledgerPath, 'utf8')).total)}`);
}

// --- 5. request body actually sent by real SDK (stub fetch) contains no key; check auth header is the only place ---
{
  const spend = createSpendGuard({ capUsd: 1 });
  let seen: { url: string; headers: Record<string, string>; body: any } | null = null;
  const stubFetch = async (url: any, init: any): Promise<Response> => {
    seen = { url: String(url), headers: Object.fromEntries(new Headers(init.headers).entries()), body: JSON.parse(init.body) };
    return new Response(JSON.stringify({ id: 'm', type: 'message', role: 'assistant', model: 'x', content: [{ type: 'text', text: JSON.stringify(wire) }], stop_reason: 'end_turn', stop_sequence: null, usage: { input_tokens: 1, output_tokens: 1, output_tokens_details: null } }), { status: 200, headers: { 'content-type': 'application/json' } });
  };
  const sdk = new Anthropic({ apiKey: 'placeholder-not-a-key', fetch: stubFetch as any });
  await createAnthropicProvider({ apiKey: 'placeholder-not-a-key', spend, client: sdk as unknown as MessagesClientLike }).complete(req);
  const s = seen as any;
  console.log(`[5] url=${s.url} body keys=${Object.keys(s.body).join(',')} max_tokens=${s.body.max_tokens} thinking=${JSON.stringify(s.body.thinking)} header names=${Object.keys(s.headers).join(',')}`);
}

// --- 6. SDK error object shape: does the thrown APIError carry headers (x-api-key) and request body echo? (what TAILOR_PROVIDER_DEBUG could reach) ---
{
  const stubFetch = async (): Promise<Response> => new Response(JSON.stringify({ type: 'error', error: { type: 'invalid_request_error', message: 'echo: hello there SECRET-BUYER-TEXT' }, request_id: 'req_1' }), { status: 400, headers: { 'content-type': 'application/json', 'request-id': 'req_1' } });
  const sdk = new Anthropic({ apiKey: 'placeholder-not-a-key', fetch: stubFetch as any });
  try { await sdk.messages.create({ model: 'claude-sonnet-5-5', max_tokens: 5, messages: [{ role: 'user', content: 'x' }] }); }
  catch (e: any) {
    console.log(`[6] error class=${e.constructor.name} status=${e.status} message="${String(e.message).slice(0, 120)}" own-keys=${Object.keys(e).join(',')} has headers=${typeof e.headers} auth header in e.headers=${e.headers?.get?.('x-api-key') ?? 'absent'}`);
  }
}

// Lane 4 scratch child: mock server with a slow explain step so the parent can SIGKILL it after the save committed.
import { Store } from '/tmp/tailor-peer-review/snapshot/src/store.ts';
import { appServer } from '/tmp/tailor-peer-review/snapshot/src/server.ts';
import { createTelemetry } from '/tmp/tailor-peer-review/snapshot/src/telemetry.ts';
import { createAgentService } from '/tmp/tailor-peer-review/snapshot/src/agent/service.ts';
import { createMockProvider } from '/tmp/tailor-peer-review/snapshot/src/agent/mock-provider.ts';
import { loadKnowledge } from '/tmp/tailor-peer-review/snapshot/src/knowledge.ts';

const dbPath = process.env.LANE4_DB!;
const port = Number(process.env.LANE4_PORT);
const planDelay = Number(process.env.LANE4_PLAN_DELAY ?? 0);
const explainDelay = Number(process.env.LANE4_EXPLAIN_DELAY ?? 0);
