const base = createMockProvider();
const provider = {
  ...base,
  async complete(req: any, signal?: AbortSignal) { if (planDelay) await new Promise(r => setTimeout(r, planDelay)); return base.complete(req, signal); },
  ...(explainDelay ? { async explain() { await new Promise(r => setTimeout(r, explainDelay)); return { explanation: { text: 'The booking call failed and the retry recovered.', spanIds: [] }, usage: null, latencyMs: 1 }; } } : {}),
};
const server = appServer(store, { devKey: 'lane4dev', agent: createAgentService(), provider, knowledge: loadKnowledge(), telemetry });
server.listen(port, '127.0.0.1', () => console.log('child-ready'));

// Lane 4 scratch: truthfulness of non-success outcomes through the real HTTP route, using scripted providers + Store faults.
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { Store } from '/tmp/tailor-peer-review/snapshot/src/store.ts';
import { appServer } from '/tmp/tailor-peer-review/snapshot/src/server.ts';
import { createTelemetry } from '/tmp/tailor-peer-review/snapshot/src/telemetry.ts';
import { createAgentService } from '/tmp/tailor-peer-review/snapshot/src/agent/service.ts';
import { createMockProvider } from '/tmp/tailor-peer-review/snapshot/src/agent/mock-provider.ts';
import { ProviderError } from '/tmp/tailor-peer-review/snapshot/src/agent/provider-error.ts';
import { loadKnowledge } from '/tmp/tailor-peer-review/snapshot/src/knowledge.ts';
import { travelBuyerTurn1 } from '/tmp/tailor-peer-review/snapshot/src/examples/travel-booking.ts';

const PORT = 4344;
const flags = { failReadback: false, failSave: false };
const hooks: { beforePlan?: () => void; explain?: () => void; planError?: Error } = {};
const dir = mkdtempSync(join(tmpdir(), 'lane4-outcomes-'));
const store = new Store(join(dir, 'db.sqlite'), { faults: { failReadback: () => flags.failReadback, failSave: () => flags.failSave } });
const telemetry = await createTelemetry({ mode: 'captured', secret: store.secret });
const base = createMockProvider();
const provider = {
  ...base,
  async complete(req: any, signal?: AbortSignal) { if (hooks.planError) throw hooks.planError; hooks.beforePlan?.(); return base.complete(req, signal); },
  async explain() { hooks.explain?.(); return { explanation: { text: 'The booking call failed and the retry recovered.', spanIds: [] }, usage: null, latencyMs: 1 }; },
};
const server = appServer(store, { devKey: 'lane4dev', agent: createAgentService(), provider, knowledge: loadKnowledge(), telemetry });
await new Promise<void>(r => server.listen(PORT, '127.0.0.1', r));
const origin = `http://127.0.0.1:${PORT}`;

async function call(path: string, method = 'GET', data?: unknown, cookie = '') {
  const res = await fetch(origin + path, { method, headers: { cookie, 'content-type': 'application/json', 'idempotency-key': randomUUID(), 'x-tailor-dev-key': 'lane4dev' }, body: data ? JSON.stringify(data) : undefined });
  const text = await res.text();
  return { status: res.status, data: text ? JSON.parse(text) : null, cookie: res.headers.get('set-cookie')?.split(';')[0] ?? cookie };
}
async function newSession(label: string) {
  const s = await call('/api/sessions', 'POST', { description: `lane4 ${label}` });
  return { id: s.data.id as string, cookie: s.cookie };
}
const turn = (s: { id: string; cookie: string }, text: string, clientTurnId = randomUUID()) => call(`/api/sessions/${s.id}/turns`, 'POST', { text, clientTurnId }, s.cookie);
const show = (label: string, r: any) => {
  const d = r.data;
  console.log(`\n=== ${label} === HTTP ${r.status} outcome=${d.outcome} version=${d.version} convVersion=${d.conversationVersion}`);
  for (const m of d.messages ?? []) console.log(`  [${m.role}/${m.status}] ${String(m.text).slice(0, 330)}`);
  console.log(`  steps: ${(d.steps ?? []).map((s: any) => `${s.name}:${s.status}${s.detail ? `(${s.detail})` : ''}`).join(' ')}`);
};
const live = async (s: any) => (await call(`/api/sessions/${s.id}`, 'GET', undefined, s.cookie)).data;

try {
  // B1: readback_uncertain, then reconcile on next turn
  { const s = await newSession('b1'); flags.failReadback = true;
    const r = await turn(s, travelBuyerTurn1.text); show('B1 readback_uncertain (failReadback)', r);
    flags.failReadback = false; const after = await live(s);
    console.log(`  authoritative session after: version=${after.version} traces=${after.dataset.traces.length} buyer-turn-status=${after.conversation[0].status}`);
    const r2 = await turn(s, 'Explain this trace'); show('B1b next turn after uncertain (faults off)', r2);
    const r3 = await turn(s, 'Make the retry fail too'); show('B1c follow-up edit after uncertain', r3);
  }
  // B2: save_failed
  { const s = await newSession('b2'); flags.failSave = true;
    const r = await turn(s, travelBuyerTurn1.text); show('B2 save_failed (failSave)', r); flags.failSave = false;
    console.log(`  authoritative version=${(await live(s)).version}`);
  }
  // B3: conflict (another writer bumps the version while the model is planning)
  { const s = await newSession('b3');
    hooks.beforePlan = () => { const cur = store.read(s.id); store.applyScenario(s.id, 'exhausted', cur.version); hooks.beforePlan = undefined; };
    const r = await turn(s, travelBuyerTurn1.text); show('B3 conflict (version bumped mid-plan)', r);
    console.log(`  authoritative version=${(await live(s)).version}`);
  }
  // B4: provider_unavailable (auth), spend_cap
  for (const kind of ['auth', 'spend_cap', 'rate_limit'] as const) {
    const s = await newSession('b4'); hooks.planError = new ProviderError(kind, 'x');
    const r = await turn(s, travelBuyerTurn1.text); show(`B4 provider_unavailable kind=${kind}`, r); hooks.planError = undefined;
  }
  // B5: committed claim downgraded by server.sanitise because ANOTHER writer bumped version after readback (during explain)
  { const s = await newSession('b5');
    hooks.explain = () => { const cur = store.read(s.id); store.applyScenario(s.id, 'exhausted', cur.version); hooks.explain = undefined; };
    const r = await turn(s, travelBuyerTurn1.text); show('B5 committed->downgraded (version moved after readback)', r);
    console.log(`  authoritative version=${(await live(s)).version}`);
  }
  // B6: conversation cap
  { const s = await newSession('b6'); let last: any;
    for (let i = 0; i < 62; i++) last = await turn(s, i % 2 ? 'Explain this trace' : 'What is a trace?');
    const sess = await live(s);
    console.log(`\n=== B6 conversation cap === after 62 turns: conversation.length=${sess.conversation.length} truncated=${sess.conversationTruncated} lastOutcome=${last.data.outcome} HTTP ${last.status}`);
  }
  // B7: client disconnect mid-turn
  { const s = await newSession('b7'); hooks.beforePlan = undefined;
    const slow = base.complete; (provider as any).complete = async (req: any, sig?: AbortSignal) => { await new Promise(r => setTimeout(r, 700)); return slow(req, sig); };
    const id = randomUUID(); const ac = new AbortController();
    const p = fetch(`${origin}/api/sessions/${s.id}/turns`, { method: 'POST', signal: ac.signal, headers: { cookie: s.cookie, 'content-type': 'application/json' }, body: JSON.stringify({ text: travelBuyerTurn1.text, clientTurnId: id }) }).catch(e => `aborted:${e.name}`);
    await new Promise(r => setTimeout(r, 150)); ac.abort(); console.log(`\n=== B7 client disconnect === client aborted -> ${await p}`);
    const during = await turn(s, 'Explain this trace'); console.log(`  new turn during orphaned work: HTTP ${during.status} ${during.data?.error?.code ?? during.data?.outcome}`);
    await new Promise(r => setTimeout(r, 1200));
    const sess = await live(s); console.log(`  after server finished: version=${sess.version} conversation=${sess.conversation.map((m: any) => `${m.role}/${m.status}`).join(',')}`);
    const replay = await turn(s, travelBuyerTurn1.text, id); console.log(`  replay same clientTurnId: HTTP ${replay.status} outcome=${replay.data.outcome} version=${replay.data.version} (no new version expected)`);
    (provider as any).complete = async (req: any, sig?: AbortSignal) => { if (hooks.planError) throw hooks.planError; hooks.beforePlan?.(); return base.complete(req, sig); };
  }
  // B8: replay only covers the LAST turn
  { const s = await newSession('b8'); const idA = randomUUID();
    const a = await turn(s, 'What is a trace?', idA); const b = await turn(s, 'Explain this trace');
    const replayA = await turn(s, 'What is a trace?', idA);
    const sess = await live(s);
    console.log(`\n=== B8 replay of an older clientTurnId === first=${a.data.outcome} second=${b.data.outcome} replay-of-first -> replayed? ${replayA.data.turnId === a.data.turnId} conversation.length=${sess.conversation.length} (4 = no dup, 6 = new duplicate turn ran)`);
  }
  // Telemetry attributes of everything captured: any buyer text / ids?
  const spans = telemetry.captured();
  const attrKeys = new Set<string>(); const evKeys = new Set<string>();
  for (const sp of spans) { Object.keys(sp.attributes).forEach(k => attrKeys.add(k)); sp.events.forEach(e => { evKeys.add(e.name); Object.keys(e.attributes).forEach(k => evKeys.add(`  ${e.name}.${k}`)); }); }
  console.log(`\n=== captured spans: ${spans.length}; attribute keys: ${[...attrKeys].sort().join(', ')}`);
  console.log(`events/keys: ${[...evKeys].sort().join(' | ')}`);
  const blob = JSON.stringify(spans);
  console.log(`contains buyer text? ${blob.includes('booking')} contains session id? ${/[0-9a-f]{8}-[0-9a-f]{4}-/.test(blob.replace(/tailor\.turn_id":"[^"]+"/g, ''))} contains cookie? ${blob.includes('tailor=')}`);
} finally {
  await new Promise<void>(r => server.close(() => r()));
  await telemetry.shutdown(); store.close();
}

// Lane 4 scratch: what do captured spans carry for error paths with hostile error content? No network.
import { Store } from '/tmp/tailor-peer-review/snapshot/src/store.ts';
import { createTelemetry, maskSpanData } from '/tmp/tailor-peer-review/snapshot/src/telemetry.ts';
import { createAgentService } from '/tmp/tailor-peer-review/snapshot/src/agent/service.ts';
import { createMockProvider } from '/tmp/tailor-peer-review/snapshot/src/agent/mock-provider.ts';
import { ProviderError } from '/tmp/tailor-peer-review/snapshot/src/agent/provider-error.ts';
import { appServer } from '/tmp/tailor-peer-review/snapshot/src/server.ts';
import { loadKnowledge } from '/tmp/tailor-peer-review/snapshot/src/knowledge.ts';
import { randomUUID } from 'node:crypto';

const SECRET_TEXT = 'BUYERSECRET-sk-ant-api03-ABCDEF';
const store = new Store(':memory:');
const telemetry = await createTelemetry({ mode: 'captured', secret: store.secret });
const base = createMockProvider();
let mode: 'throw-plain' | 'throw-provider' | 'ok' = 'throw-plain';
const provider = {
  ...base,
  async complete(req: any, sig?: AbortSignal) {
    if (mode === 'throw-plain') { const e: any = new Error(`upstream said: ${SECRET_TEXT}`); e.code = 'ECONNRESET'; e.name = 'FetchError'; throw e; }
    if (mode === 'throw-provider') throw new ProviderError('invalid_request', `echo ${SECRET_TEXT}`, { requestId: 'req_abc123' });
    return base.complete(req, sig);
  },
};
const server = appServer(store, { devKey: 'k', agent: createAgentService(), provider, knowledge: loadKnowledge(), telemetry });
await new Promise<void>(r => server.listen(4344, '127.0.0.1', r));
const origin = 'http://127.0.0.1:4344';
const s = await (await fetch(`${origin}/api/sessions`, { method: 'POST', headers: { 'content-type': 'application/json', 'idempotency-key': randomUUID() }, body: JSON.stringify({ description: `desc ${SECRET_TEXT}` }) }));
const cookie = s.headers.get('set-cookie')!.split(';')[0]!; const sess: any = await s.json();
for (const m of ['throw-plain', 'throw-provider'] as const) {
  mode = m;
  await fetch(`${origin}/api/sessions/${sess.id}/turns`, { method: 'POST', headers: { cookie, 'content-type': 'application/json' }, body: JSON.stringify({ text: `buy ${SECRET_TEXT}`, clientTurnId: randomUUID() }) });
}
const spans = telemetry.captured();
const blob = JSON.stringify(spans);
console.log('secret text anywhere in captured spans:', blob.includes(SECRET_TEXT), '| sk-ant:', blob.includes('sk-ant'), '| cookie:', blob.includes(cookie.split('=')[1]!.slice(0, 20)), '| raw session id:', blob.includes(sess.id));
for (const sp of spans) for (const e of sp.events) {
  if (e.name === 'exception' || e.name.includes('provider_error') || e.name.includes('provider_request_id') || e.name.includes('agent_error')) console.log(`event ${e.name} on span ${sp.name}:`, JSON.stringify(e.attributes).slice(0, 300));
}
// What the neatlogs export mask would let through for those same spans (attributes + events):
let kept = 0; let removedEvents = 0;
for (const sp of spans) {
  const masked: any = maskSpanData({ attributes: sp.attributes, events: sp.events, status: sp.status } as any);
  kept += Object.keys(masked.attributes).length; removedEvents += sp.events.length - masked.events.length;
  if (JSON.stringify(masked).includes(SECRET_TEXT)) console.log('LEAK after mask on', sp.name);
}
console.log(`after maskSpanData: attributes kept=${kept}, events dropped=${removedEvents}, no leak of secret text`);
console.log('diagnostics:', JSON.stringify(telemetry.diagnostics()));
await new Promise<void>(r => server.close(() => r())); await telemetry.shutdown(); store.close();

// Lane 4 scratch: SIGKILL the server mid-turn, reopen the SQLite file, retry the same clientTurnId.
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { Store } from '/tmp/tailor-peer-review/snapshot/src/store.ts';
import { travelBuyerTurn1 } from '/tmp/tailor-peer-review/snapshot/src/examples/travel-booking.ts';

const PORT = 4344;
const origin = `http://127.0.0.1:${PORT}`;
const sleep = (ms: number) => new Promise(r => setTimeout(r, ms));
async function startChild(db: string, env: Record<string, string>) {
  const child = spawn('node', ['/tmp/tailor-peer-review/lane4/child-server.ts'], { env: { PATH: process.env.PATH!, LANE4_DB: db, LANE4_PORT: String(PORT), ...env }, stdio: ['ignore', 'pipe', 'inherit'] });
  await new Promise<void>((res, rej) => { child.stdout!.on('data', d => { if (String(d).includes('child-ready')) res(); }); child.on('exit', c => rej(new Error(`child exited ${c}`))); });
  return child;
}
const j = async (path: string, method = 'GET', data?: unknown, cookie = '') => {
  const r = await fetch(origin + path, { method, headers: { cookie, 'content-type': 'application/json', 'idempotency-key': randomUUID(), 'x-tailor-dev-key': 'lane4dev' }, body: data ? JSON.stringify(data) : undefined });
  const t = await r.text(); return { status: r.status, data: t ? JSON.parse(t) : null, cookie: r.headers.get('set-cookie')?.split(';')[0] ?? cookie };
};
const summary = (s: any) => `version=${s.version} conv=[${s.conversation.map((m: any) => `${m.role}/${m.status}`).join(', ')}]`;

async function scenario(label: string, childEnv: Record<string, string>, killAfterMs: number) {
  const dir = mkdtempSync(join(tmpdir(), 'lane4-kill-'));
  const db = join(dir, 'db.sqlite');
  let child = await startChild(db, childEnv);
  const created = await j('/api/sessions', 'POST', { description: 'lane4 kill' });
  const { id } = created.data; const cookie = created.cookie;
  const clientTurnId = randomUUID();
  void fetch(`${origin}/api/sessions/${id}/turns`, { method: 'POST', headers: { cookie, 'content-type': 'application/json' }, body: JSON.stringify({ text: travelBuyerTurn1.text, clientTurnId }) }).catch(() => {});
  await sleep(killAfterMs);
  child.kill('SIGKILL'); await new Promise(r => child.on('exit', r));
